<template><view class="page"><view class="head"><text class="title">充值积分</text><text class="sub">支付完成后提交核验，管理员确认后自动到账。</text></view><view class="card"><text class="balance">当前积分 <text>{{ balance }}</text></text><text class="rules">文生图 16 积分 · 文生3D 60 积分 · 图生3D 70 积分</text></view><view class="section"><text class="label">选择充值套餐</text><view v-for="pkg in packages" :key="pkg.code" class="pkg" :class="{selected:selected?.code===pkg.code}" @tap="selected=pkg"><view><text class="pkg-name">{{ pkg.name }}</text><text class="pkg-credit">{{ pkg.credits }} 积分</text></view><text class="price">¥{{ pkg.amount }}</text></view></view><button class="pay" :disabled="!selected" :loading="loading" @tap="order">{{ selected?`生成 ${selected.name} 收款码`:'请选择套餐' }}</button><view v-if="paymentOrder" class="modal"><view class="sheet"><text class="sheet-title">请使用微信扫码付款</text><image v-if="qrUrl" :src="qrUrl" class="qr" mode="aspectFit"/><text class="order">订单号：{{ paymentOrder.orderNo }}</text><text class="order">支付后请点击下方按钮提交人工核验。</text><button class="done" :loading="loading" @tap="complete">我已完成支付</button><text class="close" @tap="paymentOrder=null">暂不支付</text></view></view></view></template>
<script setup lang="ts">import { onMounted, ref } from 'vue';import { createPaymentOrder,getCredits,getPackages,manualComplete } from '../../api/creative';import { imageUrl } from '../../utils/format';import { requireSession } from '../../utils/session';const packages=ref<any[]>([]),selected=ref<any>(null),balance=ref(0),loading=ref(false),paymentOrder=ref<any>(null),qrUrl=ref('');onMounted(async()=>{if(!requireSession())return;try{const [p,c]=await Promise.all([getPackages(),getCredits()]);packages.value=p.items||[];balance.value=c.balance||0}catch(e:any){uni.showToast({title:e.message||'加载充值信息失败',icon:'none'})}});async function order(){if(!selected.value)return;loading.value=true;try{paymentOrder.value=await createPaymentOrder(selected.value.code);qrUrl.value=imageUrl(paymentOrder.value.codeUrl||'/payment-collection-qr.jpg')}catch(e:any){uni.showToast({title:e.message||'创建订单失败',icon:'none'})}finally{loading.value=false}}async function complete(){loading.value=true;try{paymentOrder.value=await manualComplete(paymentOrder.value.orderNo);uni.showModal({title:'已提交核验',content:'管理员确认收款后，积分将自动发放到你的账户。',showCancel:false})}catch(e:any){uni.showToast({title:e.message||'提交失败',icon:'none'})}finally{loading.value=false}}</script>
<style scoped lang="scss">.page{min-height:100vh;padding:34rpx}.head{padding:20rpx 4rpx 30rpx}.title{display:block;font-size:48rpx;font-weight:800}.sub{display:block;font-size:23rpx;color:#8d7469;margin-top:12rpx;line-height:1.6}.card{background:linear-gradient(135deg,#472015,#a94c2b);border-radius:25rpx;color:#fff;padding:34rpx}.balance{font-size:24rpx;display:block}.balance text{font-size:62rpx;font-weight:800;margin-left:16rpx}.rules{font-size:21rpx;color:#f4d7c4;margin-top:20rpx;display:block}.section{margin-top:36rpx}.label{font-size:30rpx;font-weight:700}.pkg{display:flex;justify-content:space-between;align-items:center;margin-top:18rpx;background:#fff;border:2rpx solid transparent;border-radius:20rpx;padding:26rpx}.pkg.selected{border-color:#a64a2b;background:#fff8f2}.pkg-name,.pkg-credit{display:block}.pkg-name{font-size:29rpx;font-weight:700}.pkg-credit{font-size:22rpx;color:#936f5f;margin-top:8rpx}.price{font-size:38rpx;font-weight:800;color:#9e4325}.pay,.done{height:94rpx;line-height:94rpx;background:#963c23;color:#fff;border-radius:48rpx;font-size:29rpx;margin-top:40rpx}.pay[disabled]{opacity:.4}.modal{position:fixed;inset:0;background:rgba(0,0,0,.48);display:flex;align-items:flex-end}.sheet{width:100%;background:#fff;border-radius:34rpx 34rpx 0 0;padding:44rpx;box-sizing:border-box;text-align:center}.sheet-title{font-size:34rpx;font-weight:700}.qr{width:420rpx;height:420rpx;margin:24rpx auto}.order{display:block;font-size:21rpx;color:#947a6d;line-height:1.7}.done{margin-top:25rpx}.close{display:block;padding:25rpx;color:#8e7469;font-size:26rpx}</style>
